<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';if(current_merchant()){redirect_to('/dashboard.php');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();rate_limit('register',5,3600);$name=trim((string)($_POST['name']??''));$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');if(strlen($name)<2||strlen($name)>120||!$email||strlen($password)<12||$password!==($_POST['confirm_password']??''))$error='Use a valid name and email, and a matching password of at least 12 characters.';else{try{$key='tg_'.bin2hex(random_bytes(30));$q=db()->prepare('INSERT INTO merchants(name,email,password,api_key) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$key]);session_regenerate_id(true);$_SESSION['merchant_id']=(int)db()->lastInsertId();$_SESSION['merchant_name']=$name;$_SESSION['merchant_email']=$email;redirect_to('/integrations.php');}catch(PDOException $e){if((string)$e->getCode()==='23000'||in_array((int)($e->errorInfo[1]??0),[19,1062],true))$error='An account with that email already exists.';else{$error='Could not create your account.';error_log($e->getMessage());}}}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create account — TG Gateways</title><link rel="stylesheet" href="/assets/css/style.css"></head><body class="auth-wrap"><main class="auth-card"><a class="brand" href="/"><img src="/assets/img/logo.svg" alt="">TG Gateways</a><h1>Create your merchant account</h1><p>This self-hosted starter creates a dashboard account. Configure your receiving account and review your local provider requirements before processing payments.</p><?php if($error):?><div class="note" style="color:#963d3d;background:#fff6f5;border-color:#f3d2d2"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Business / display name</label><input name="name" maxlength="120" required></div><div class="field"><label>Email</label><input type="email" name="email" required autocomplete="email"></div><div class="field"><label>Password · 12 characters minimum</label><input type="password" name="password" minlength="12" required autocomplete="new-password"></div><div class="field"><label>Confirm password</label><input type="password" name="confirm_password" minlength="12" required autocomplete="new-password"></div><button class="btn">Create account →</button></form><p style="margin-top:18px">Already registered? <a href="/login.php" style="color:var(--blue)">Sign in</a></p></main></body></html>
